-- GTRP Unified License System - initial schema (D1 / SQLite)
-- Conventions:
--   * ids are random UUIDv4 strings generated by the application
--   * timestamps are ISO 8601 UTC strings with millisecond precision and a trailing Z
--     (e.g. 2026-10-25T09:57:41.000Z) so lexicographic order == chronological order
--   * secrets (license keys, session tokens, device ids, account refs) are stored only as keyed hashes
--   * foreign keys are enforced by D1 by default

CREATE TABLE users (
  id                  TEXT PRIMARY KEY NOT NULL,
  email               TEXT NOT NULL COLLATE NOCASE,
  password_hash       TEXT,
  role                TEXT NOT NULL DEFAULT 'customer' CHECK (role IN ('customer', 'admin')),
  status              TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'deleted')),
  mfa_secret_enc      TEXT,
  mfa_enabled         INTEGER NOT NULL DEFAULT 0 CHECK (mfa_enabled IN (0, 1)),
  failed_login_count  INTEGER NOT NULL DEFAULT 0 CHECK (failed_login_count >= 0),
  locked_until        TEXT,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL,
  deleted_at          TEXT,
  CHECK (status <> 'deleted' OR deleted_at IS NOT NULL)
);
CREATE UNIQUE INDEX users_email_uq ON users (email);
CREATE INDEX users_role_status_idx ON users (role, status);
CREATE INDEX users_created_at_idx ON users (created_at);

CREATE TABLE plans (
  id                    TEXT PRIMARY KEY NOT NULL,
  code                  TEXT NOT NULL,
  name                  TEXT NOT NULL,
  price_minor           INTEGER NOT NULL CHECK (price_minor >= 0),
  currency              TEXT NOT NULL CHECK (length(currency) = 3 AND currency = upper(currency)),
  billing_period        TEXT NOT NULL CHECK (billing_period IN ('monthly', 'yearly', 'lifetime')),
  max_web_devices       INTEGER NOT NULL CHECK (max_web_devices >= 0),
  max_ea_activations    INTEGER NOT NULL CHECK (max_ea_activations >= 0),
  max_trading_accounts  INTEGER NOT NULL CHECK (max_trading_accounts >= 0),
  features_json         TEXT NOT NULL CHECK (json_valid(features_json)),
  is_active             INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  created_at            TEXT NOT NULL,
  updated_at            TEXT NOT NULL
);
CREATE UNIQUE INDEX plans_code_uq ON plans (code);

CREATE TABLE licenses (
  id           TEXT PRIMARY KEY NOT NULL,
  user_id      TEXT NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
  plan_id      TEXT NOT NULL REFERENCES plans (id) ON DELETE RESTRICT,
  -- HMAC-SHA256(LICENSE_KEY_PEPPER, normalized key). NULL until a key is issued
  -- (e.g. a license created by a verified payment before the customer reveals a key).
  key_hash     TEXT,
  -- Last 4 characters of the key, for operators to identify it. Never the full key.
  key_hint     TEXT,
  status       TEXT NOT NULL CHECK (status IN ('created', 'active', 'expired', 'suspended', 'revoked')),
  starts_at    TEXT NOT NULL,
  expires_at   TEXT,
  grace_until  TEXT,
  note         TEXT,
  -- Optimistic-concurrency counter; every state change does "WHERE version = ?".
  version      INTEGER NOT NULL DEFAULT 1,
  -- Random id of the last write; lets an audit INSERT in the same batch run only if that write applied.
  last_op_id   TEXT,
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL,
  CHECK (expires_at IS NULL OR expires_at > starts_at),
  CHECK (grace_until IS NULL OR (expires_at IS NOT NULL AND grace_until >= expires_at))
);
CREATE UNIQUE INDEX licenses_key_hash_uq ON licenses (key_hash) WHERE key_hash IS NOT NULL;
CREATE INDEX licenses_user_idx ON licenses (user_id);
CREATE INDEX licenses_plan_idx ON licenses (plan_id);
CREATE INDEX licenses_status_expires_idx ON licenses (status, expires_at);

-- A NULL expires_at (no expiry) is only allowed for plans explicitly configured as lifetime.
CREATE TRIGGER licenses_lifetime_only_insert
BEFORE INSERT ON licenses
WHEN NEW.expires_at IS NULL
  AND (SELECT billing_period FROM plans WHERE id = NEW.plan_id) IS NOT 'lifetime'
BEGIN
  SELECT RAISE(ABORT, 'expires_at may only be NULL for lifetime plans');
END;

CREATE TRIGGER licenses_lifetime_only_update
BEFORE UPDATE OF expires_at, plan_id ON licenses
WHEN NEW.expires_at IS NULL
  AND (SELECT billing_period FROM plans WHERE id = NEW.plan_id) IS NOT 'lifetime'
BEGIN
  SELECT RAISE(ABORT, 'expires_at may only be NULL for lifetime plans');
END;

-- Revoked is terminal: block any attempt to move a revoked license to another status.
CREATE TRIGGER licenses_revoked_is_terminal
BEFORE UPDATE OF status ON licenses
WHEN OLD.status = 'revoked' AND NEW.status <> 'revoked'
BEGIN
  SELECT RAISE(ABORT, 'revoked licenses cannot change status');
END;

CREATE TABLE activations (
  id                TEXT PRIMARY KEY NOT NULL,
  license_id        TEXT NOT NULL REFERENCES licenses (id) ON DELETE CASCADE,
  activation_type   TEXT NOT NULL CHECK (activation_type IN ('web', 'mt4', 'mt5')),
  product           TEXT NOT NULL,
  -- HMAC of the client-generated installation / browser id (not a hardware fingerprint)
  device_hash       TEXT NOT NULL,
  -- HMAC of the trading-account reference, only when the plan binds EAs to accounts
  account_ref_hash  TEXT,
  label             TEXT,
  status            TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked')),
  first_seen_at     TEXT NOT NULL,
  last_seen_at      TEXT NOT NULL,
  revoked_at        TEXT,
  revoked_reason    TEXT,
  CHECK (activation_type <> 'web' OR account_ref_hash IS NULL)
);
-- Activation identity: one row per (license, platform, installation).
CREATE UNIQUE INDEX activations_identity_uq ON activations (license_id, activation_type, device_hash);
CREATE INDEX activations_license_status_idx ON activations (license_id, status, activation_type);
CREATE INDEX activations_type_last_seen_idx ON activations (activation_type, last_seen_at);

CREATE TABLE sessions (
  id            TEXT PRIMARY KEY NOT NULL,
  user_id       TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  token_hash    TEXT NOT NULL,
  mfa_verified  INTEGER NOT NULL DEFAULT 0 CHECK (mfa_verified IN (0, 1)),
  expires_at    TEXT NOT NULL,
  revoked_at    TEXT,
  created_at    TEXT NOT NULL,
  last_used_at  TEXT NOT NULL
);
CREATE UNIQUE INDEX sessions_token_hash_uq ON sessions (token_hash);
CREATE INDEX sessions_user_idx ON sessions (user_id);
CREATE INDEX sessions_expires_idx ON sessions (expires_at);

CREATE TABLE payments (
  id                  TEXT PRIMARY KEY NOT NULL,
  user_id             TEXT NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
  license_id          TEXT REFERENCES licenses (id) ON DELETE RESTRICT,
  plan_id             TEXT NOT NULL REFERENCES plans (id) ON DELETE RESTRICT,
  provider            TEXT NOT NULL,
  provider_ref        TEXT NOT NULL,
  amount_minor        INTEGER NOT NULL CHECK (amount_minor >= 0),
  currency            TEXT NOT NULL CHECK (length(currency) = 3),
  status              TEXT NOT NULL CHECK (status IN ('pending', 'paid', 'failed', 'refunded')),
  -- provider event id that moved this payment to "paid" (idempotency anchor for renewals)
  paid_event_id       TEXT,
  paid_at             TEXT,
  refunded_at         TEXT,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL,
  CHECK (status <> 'paid' OR paid_at IS NOT NULL)
);
CREATE UNIQUE INDEX payments_provider_ref_uq ON payments (provider, provider_ref);
CREATE INDEX payments_user_idx ON payments (user_id);
CREATE INDEX payments_license_idx ON payments (license_id);
CREATE INDEX payments_status_created_idx ON payments (status, created_at);

-- Every webhook event received, keyed by the provider's event id (duplicate/replay gate).
CREATE TABLE payment_events (
  id                 TEXT PRIMARY KEY NOT NULL,
  provider           TEXT NOT NULL,
  provider_event_id  TEXT NOT NULL,
  payment_id         TEXT REFERENCES payments (id) ON DELETE SET NULL,
  event_type         TEXT NOT NULL,
  -- SHA-256 of the raw body; the body itself is not stored
  payload_sha256     TEXT NOT NULL,
  result             TEXT NOT NULL,
  received_at        TEXT NOT NULL
);
CREATE UNIQUE INDEX payment_events_provider_event_uq ON payment_events (provider, provider_event_id);
CREATE INDEX payment_events_payment_idx ON payment_events (payment_id);

-- Audit log for license and account changes (append-only by convention; no UPDATE/DELETE in code).
CREATE TABLE license_events (
  id              TEXT PRIMARY KEY NOT NULL,
  license_id      TEXT REFERENCES licenses (id) ON DELETE SET NULL,
  actor_user_id   TEXT REFERENCES users (id) ON DELETE SET NULL,
  actor_type      TEXT NOT NULL CHECK (actor_type IN ('admin', 'customer', 'system', 'client', 'provider')),
  target_user_id  TEXT REFERENCES users (id) ON DELETE SET NULL,
  event_type      TEXT NOT NULL,
  details_json    TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(details_json)),
  created_at      TEXT NOT NULL
);
CREATE INDEX license_events_license_idx ON license_events (license_id, created_at);
CREATE INDEX license_events_created_idx ON license_events (created_at);
CREATE INDEX license_events_actor_idx ON license_events (actor_user_id, created_at);
CREATE INDEX license_events_target_idx ON license_events (target_user_id, created_at);
CREATE INDEX license_events_type_idx ON license_events (event_type, created_at);

CREATE TRIGGER license_events_no_update
BEFORE UPDATE ON license_events
BEGIN
  SELECT RAISE(ABORT, 'audit events are append-only');
END;

-- Fixed-window counters for login/registration/validation rate limiting.
-- One atomic UPSERT per request; old windows are purged by the scheduled job.
CREATE TABLE api_rate_limits (
  bucket        TEXT NOT NULL,
  window_start  INTEGER NOT NULL,
  count         INTEGER NOT NULL,
  PRIMARY KEY (bucket, window_start)
) WITHOUT ROWID;

-- Request ids seen from EA/web protocol clients (replay protection).
CREATE TABLE request_nonces (
  nonce_hash  TEXT PRIMARY KEY NOT NULL,
  expires_at  TEXT NOT NULL
) WITHOUT ROWID;
CREATE INDEX request_nonces_expires_idx ON request_nonces (expires_at);
